(()=>{
let tab='Summary',day='2026-09-13',span='Day',compare=false,chartType='bars';const hidden=new Set();let buyRate=8,sellRate=3;const rupees=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(v);const cost=()=>4.5*buyRate-.1*sellRate;
const names=['Battery Input','Returned to grid low tariff','Returned to grid high tariff','Solar','Battery','Grid consumption low tariff','Grid consumption high tariff'];
const appliances=['Electric car','Air conditioning','Washing machine','Dryer','Heat pump','Boiler','Other'];
const panel=(title,body)=>`<section class="energy-card"><h2>${title}</h2>${body}</section>`;
const available=()=>{if(tab==='Now')return true;const start=new Date(day+'T00:00:00'),end=new Date(start),snapshot=new Date('2026-09-13T12:00:00');if(span==='Year')end.setFullYear(end.getFullYear()+1);else if(span==='Month')end.setMonth(end.getMonth()+1);else end.setDate(end.getDate()+(span==='Week'?7:1));return snapshot>=start&&snapshot<end};
const empty=()=>'<div class="energy-empty">There is no data for this period.</div>';
function graph(title,series=names,zero=false){return panel(title,zero||!available()?empty():`<p class="energy-caption">Illustrative hourly profile · kWh</p><div class="energy-plot" role="img" aria-label="${title}: illustrative hourly profile"><div class="energy-gridlines"></div>${Array.from({length:24},(_,i)=>`<div class="energy-stack" tabindex="0" title="${String(i).padStart(2,'0')}:00 · illustrative profile">${series.filter(n=>!hidden.has(title+n)).map((n,j)=>`<i style="--series:${j%5};height:${Math.max(2,Math.round((Math.sin(i*.5+j)+1.2)*(j===0?19:10)))}px"></i>`).join('')}${compare?'<em title="Previous period: unavailable"></em>':''}</div>`).join('')}</div><div class="energy-axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>24:00</span></div><div class="energy-legend">${series.map((n,j)=>`<button data-series="${esc(title+n)}" aria-pressed="${!hidden.has(title+n)}"><i style="--series:${j%5}"></i>${n}</button>`).join('')}</div>${compare?'<p class="energy-caption">Previous-period comparison is unavailable in this demo snapshot.</p>':''}`)}
function flow(now=false){const has=available();return panel(now?'Current power flow':'Energy distribution',!has?empty():`<div class="energy-flow"><div class="flow-node solar">${icon('sun')}<b>Solar</b><strong>${now?'200 W':'1.3 kWh'}</strong><small>${now?'Generating':'1.2 used · 0.1 exported'}</small></div><div class="flow-node grid">${icon('energy')}<b>Grid</b><strong>${now?'500 W':'4.5 kWh'}</strong><small>${now?'Importing':'Imported · '+rupees(4.5*buyRate)}</small></div><div class="flow-node home">${icon('home')}<b>Home</b><strong>${now?'700 W':'5.7 kWh'}</strong><small>${now?'Consuming':'Total consumption'}</small></div><div class="flow-node battery">${icon('plug')}<b>Battery</b><strong>${now?'0 W':'0 kWh'}</strong><small>Idle</small></div>${now?'':`<div class="flow-node gas">${icon('climate')}<b>Gas</b><strong>0 m³</strong></div><div class="flow-node water">${icon('rain')}<b>Water</b><strong>0 L</strong></div>`}<svg viewBox="0 0 400 310" preserveAspectRatio="none" aria-hidden="true"><path class="flow-track" d="M200 55V150H335 M65 150H335"/><path class="flow-active solar-path" d="M200 55V150H335"/><path class="flow-active grid-path" d="M65 150H335"/></svg></div>${now?'<p class="energy-caption">200 W solar + 500 W grid = 700 W home. Simulated readings.</p>':`<div class="distribution-balance"><span>4.5 grid + 1.3 solar − 0.1 exported</span><b>= 5.7 kWh consumed</b></div><div class="rupee-total"><span>Estimated net electricity cost</span><strong>${rupees(cost())}</strong><small>${rupees(4.5*buyRate)} import − ${rupees(.1*sellRate)} export credit</small></div><div class="tariff-inputs"><label>Import · ₹/kWh<input data-tariff="buy" type="number" min="0" max="100" step="0.01" value="${buyRate}"></label><label>Export · ₹/kWh<input data-tariff="sell" type="number" min="0" max="100" step="0.01" value="${sellRate}"></label></div><p class="energy-caption">Editable example rates, not a utility tariff. Excludes fixed charges and taxes. 1 kWh = 1 electricity unit. Snapshot totals only, even for wider periods.</p>`}`)}
function totals(kind='Summary'){const rows=kind==='Gas'?[['Gas total','0 m³','Not configured']]:kind==='Water'?[['Water total','0 L','Not configured']]:kind==='Electricity'?[['Solar generation','1.3 kWh','—'],['Solar used at home','1.2 kWh','—'],['Battery total','0 kWh','—'],['Grid consumption low tariff','3.72 kWh',rupees(3.72*buyRate)],['Grid consumption high tariff','0.78 kWh',rupees(.78*buyRate)],['Returned to grid low tariff','0 kWh',rupees(0)],['Returned to grid high tariff','−0.1 kWh','−'+rupees(.1*sellRate)],['Grid net total','4.4 kWh',rupees(cost())]]:[['Solar generation','1.3 kWh','—'],['Home consumption','5.7 kWh','—'],['Battery total','0 kWh','—'],['Grid import','4.5 kWh',rupees(4.5*buyRate)],['Grid export credit','−0.1 kWh','−'+rupees(.1*sellRate)],['Grid net total','4.4 kWh',rupees(cost())],['Gas total','0 m³','Not configured'],['Water total','0 L','Not configured']];return panel('Totals',`<div class="energy-table"><table><caption>Snapshot totals · estimated costs in INR</caption><thead><tr><th>Source</th><th>Quantity</th><th>Cost</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${available()?r[1]:'—'}</td><td>${available()?r[2]:'—'}</td></tr>`).join('')}</tbody></table></div>`)}
function devicesChart(){return panel('Individual devices',`<button data-energy-chart>Change chart type</button>${!available()?empty():`<p class="energy-caption">Illustrative device breakdown</p><div class="device-energy-chart ${chartType}">${appliances.map((n,i)=>`<div><span>${n}</span><i style="width:${85-i*10}%"></i></div>`).join('')}</div>`}`)}
function mobilePicker(){return '<div class="energy-mobile-picker"><label for="energy-section-select">'+icon('energy')+' Energy</label><select id="energy-section-select" aria-label="Energy section">'+['Summary','Electricity','Gas','Water','Now'].map(t=>'<option '+(t===tab?'selected':'')+'>'+t+'</option>').join('')+'</select></div>'}
energyView=function(){let body='';if(tab==='Summary')body=flow()+totals()+graph('Power sources',['Solar','Grid','Battery','Consumption'])+graph('Electricity')+graph('Gas consumption',[],true)+graph('Water consumption',[],true);if(tab==='Electricity')body=flow()+panel('Grid energy balance',`<div class="energy-equation">${available()?'4.5 − 0.1 = <b>4.4 kWh</b>':'—'}</div><p>Imported − exported = net grid energy</p>`)+panel('Energy independence',`<div class="energy-gauges">${[['4.4 kWh','Net imported from the grid'],['92.3%','Self-consumed solar energy'],['21.1%','Self-sufficiency']].map(([v,n])=>`<div><strong>${available()?v:'—'}</strong><span>${n}</span></div>`).join('')}</div>`)+graph('Electricity')+graph('Solar production',['Solar'])+totals('Electricity')+graph('Individual devices detail',appliances)+devicesChart()+panel('Energy flow',`<div class="flow-summary"><span>Grid · 4.5 kWh</span><span>Solar · 1.3 kWh</span><b>→ Home · 5.7 kWh</b><span>→ Grid · 0.1 kWh</span></div>`);if(tab==='Gas'||tab==='Water')body=graph(tab+' consumption',[],true)+totals(tab)+(tab==='Water'?panel('Water flow',empty()):'');if(tab==='Now')body=panel('Power usage','<div class="energy-big">700 <small>W</small></div><p>Simulated current reading</p>')+graph('Power sources',['Solar','Grid','Battery','Consumption'])+flow(true);return `<div class="energy-dashboard">${mobilePicker()}<div class="energy-tabbar" role="tablist" aria-label="Energy sections">${['Summary','Electricity','Gas','Water','Now'].map(t=>`<button role="tab" aria-selected="${t===tab}" data-energy-tab="${t}">${t}</button>`).join('')}</div>${tab==='Now'?'':`<div class="energy-period"><button data-energy-prev aria-label="Previous period">‹</button><button data-energy-date aria-label="Select time period">${day} · ${span}</button><button data-energy-next aria-label="Next period">›</button><label><input type="checkbox" data-energy-compare ${compare?'checked':''}> Compare</label></div>`}<p class="energy-caption">Fosslink demo · reference snapshot for September 13, 2026. Chart profiles are illustrative; no meter is connected.</p><div class="energy-panels">${body}</div></div>`};
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const x=b.dataset;if(x.energyTab){tab=x.energyTab;render()}if(x.series){hidden.has(x.series)?hidden.delete(x.series):hidden.add(x.series);render()}if('energyChart'in x){chartType=chartType==='bars'?'rounded':'bars';render()}if('energyPrev'in x||'energyNext'in x){const d=new Date(day+'T12:00:00');const step='energyPrev'in x?-1:1;if(span==='Year')d.setFullYear(d.getFullYear()+step);else if(span==='Month')d.setMonth(d.getMonth()+step);else d.setDate(d.getDate()+step*(span==='Week'?7:1));day=d.toISOString().slice(0,10);render()}if('energyDate'in x)openModal(`<form id="energy-period-form"><h2>Select time period</h2><div class="energy-presets">${['Today','Yesterday','This week','This month'].map(n=>`<button type="button" data-energy-preset="${n}">${n}</button>`).join('')}</div><label>Start date<input name="date" type="date" value="${day}" required></label><label>Period<select name="span">${['Day','Week','Month','Year'].map(n=>`<option ${span===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="actions"><button type="button" data-close>Cancel</button><button type="submit" class="primary">Select</button></div></form>`)});
app.addEventListener('input',e=>{if(!e.target.dataset.tariff)return;const v=Number(e.target.value);if(!Number.isFinite(v)||v<0||v>100)return;if(e.target.dataset.tariff==='buy')buyRate=v;else sellRate=v;const total=app.querySelector('.rupee-total');if(total){total.querySelector('strong').textContent=rupees(cost());total.querySelector('small').textContent=rupees(4.5*buyRate)+' import − '+rupees(.1*sellRate)+' export credit'}},true);
app.addEventListener('change',e=>{if(e.target.id==='energy-section-select'){tab=e.target.value;render();app.querySelector('#energy-section-select')?.focus();return}if(e.target.dataset.tariff){const v=Number(e.target.value);if(!Number.isFinite(v)||v<0||v>100){e.target.reportValidity();return}if(e.target.dataset.tariff==='buy')buyRate=v;else sellRate=v;render();return}if('energyCompare'in e.target.dataset){compare=e.target.checked;render()}});
modal.addEventListener('click',e=>{const preset=e.target.closest('[data-energy-preset]')?.dataset.energyPreset;if(!preset)return;const d=new Date();if(preset==='Yesterday')d.setDate(d.getDate()-1);if(preset==='This week')d.setDate(d.getDate()-((d.getDay()+6)%7));if(preset==='This month')d.setDate(1);modal.querySelector('[name=date]').value=d.toISOString().slice(0,10);modal.querySelector('[name=span]').value=preset==='This week'?'Week':preset==='This month'?'Month':'Day'});
modal.addEventListener('submit',e=>{if(e.target.id!=='energy-period-form')return;e.preventDefault();const f=new FormData(e.target);day=f.get('date');span=f.get('span');modal.close();render()});
})();
